function p({registerIndicator:r,nulls:N}){r({id:"oa-wad",name:"Williams Accumulation/Distribution (WAD)",category:"Volume",placement:"pane",inputs:[],plots:[{key:"wad",type:"line",title:"WAD",style:{color:"#ffeb3b",lineWidth:2}}],calc(n){const u=n.length,s=new Array(u).fill(NaN);let c=0;for(let e=0;e<u;e++){const i=n[e],t=Number(i.close),m=Number(i.high),a=Number(i.low),o=e>0&&Number.isFinite(Number(n[e-1].close))?Number(n[e-1].close):t;let l=0;if(Number.isFinite(t)&&Number.isFinite(o)&&Number.isFinite(m)&&Number.isFinite(a)){const f=Math.max(m,o),h=Math.min(a,o);t>o?l=t-h:t<o?l=t-f:l=0}const b=Number.isFinite(i.volume)?i.volume:0;c+=l*b,s[e]=c}return{wad:N(s)}}})}export{p as default};
